import type {DynamicToolUIPart, ToolUIPart} from 'ai';
import * as stylex from '@stylexjs/stylex';
import {ChatToolCalls, type ChatToolCallStatus} from '@astryxdesign/core/Chat';
import {CodeBlock} from '@astryxdesign/core/CodeBlock';
import {VStack} from '@astryxdesign/core/Layout';
import {Text} from '@astryxdesign/core/Text';
import {summarizeArgs} from './summarize';

export type ToolPart = ToolUIPart | DynamicToolUIPart;

const STATUS: Record<ToolPart['state'], ChatToolCallStatus> = {
  'input-streaming': 'pending',
  'input-available': 'running',
  'approval-requested': 'pending',
  'approval-responded': 'running',
  'output-available': 'complete',
  'output-error': 'error',
  'output-denied': 'error',
};

const styles = stylex.create({
  code: {borderColor: 'transparent', boxShadow: 'none'},
});

const toolName = (part: ToolPart) => (part.type === 'dynamic-tool' ? part.toolName : part.type.slice(5));

function Detail({label, value}: {label: string; value: unknown}) {
  const code = typeof value === 'string' ? value : JSON.stringify(value, null, 2);
  return (
    <VStack gap={1}>
      <Text type="supporting" color="secondary">
        {label}
      </Text>
      <CodeBlock code={code} language={typeof value === 'string' ? 'text' : 'json'} maxHeight={240} xstyle={styles.code} />
    </VStack>
  );
}

export function ToolCall({part}: {part: ToolPart}) {
  const hasInput = part.state !== 'input-streaming';
  return (
    <ChatToolCalls
      calls={[
        {
          key: part.toolCallId,
          name: toolName(part),
          status: STATUS[part.state],
          target: summarizeArgs(part.input),
          errorMessage: part.state === 'output-error' ? part.errorText : undefined,
          resultDetail: hasInput ? (
            <VStack gap={2}>
              <Detail label="Arguments" value={part.input} />
              {part.state === 'output-available' && <Detail label="Result" value={part.output} />}
              {part.state === 'output-error' && <Detail label="Error" value={part.errorText} />}
            </VStack>
          ) : undefined,
        },
      ]}
    />
  );
}
EOF
cat > DeniedCall.tsx <<'EOF'
import type {DeniedCall as DeniedCallRecord} from '@/lib/agent/types';
import * as stylex from '@stylexjs/stylex';
import {Icon} from '@astryxdesign/core/Icon';
import {Text} from '@astryxdesign/core/Text';
import {Token} from '@astryxdesign/core/Token';
import {colorVars, radiusVars, spacingVars, typeScaleVars, typographyVars} from '@astryxdesign/core/theme/tokens.stylex';
import {summarizeArgs} from './summarize';

const LABEL: Record<DeniedCallRecord['reason'], string> = {
  'outside-project': 'Blocked: outside project',
  'not-allowlisted': 'Blocked: tool not allowed',
  'user-denied': 'Denied by you',
};

const styles = stylex.create({
  root: {
    display: 'flex',
    flexDirection: 'column',
    gap: spacingVars['--spacing-1'],
    marginBlockStart: spacingVars['--spacing-2'],
    paddingBlock: spacingVars['--spacing-1-5'],
    paddingInline: spacingVars['--spacing-2'],
    borderRadius: radiusVars['--radius-container'],
    backgroundColor: colorVars['--color-warning-muted'],
  },
  row: {display: 'flex', alignItems: 'center', gap: spacingVars['--spacing-1-5'], minWidth: 0},
  icon: {display: 'inline-flex', color: colorVars['--color-warning']},
  name: {
    fontFamily: typographyVars['--font-family-code'],
    fontSize: typeScaleVars['--text-supporting-size'],
    color: colorVars['--color-text-primary'],
  },
  target: {
    flexShrink: 1,
    minWidth: 0,
    overflow: 'hidden',
    textOverflow: 'ellipsis',
    whiteSpace: 'nowrap',
    fontFamily: typographyVars['--font-family-code'],
    fontSize: typeScaleVars['--text-supporting-size'],
    color: colorVars['--color-text-secondary'],
  },
});

export function DeniedCall({call}: {call: DeniedCallRecord}) {
  const target = summarizeArgs(call.args);
  return (
    <div {...stylex.props(styles.root)}>
      <div {...stylex.props(styles.row)}>
        <span {...stylex.props(styles.icon)}>
          <Icon icon="warning" size="xsm" color="inherit" />
        </span>
        <span {...stylex.props(styles.name)}>{call.tool}</span>
        {target && <span {...stylex.props(styles.target)}>{target}</span>}
        <Token label={LABEL[call.reason]} size="sm" color="orange" />
      </div>
      <Text type="supporting" color="secondary">
        {call.message}
      </Text>
    </div>
  );
}
EOF
