          <Button label="Deny" variant="secondary" size="sm" onClick={() => decide('deny')} />
        </HStack>
      ) : (
        <Text type="supporting" color="secondary" role="status">
          {choice === 'approve' ? 'Approved. The agent is continuing.' : 'Denied. The file was not changed.'}
        </Text>
      )}
    </div>
  );
}
