}));
if (shot) await p.screenshot({path: shot});
await p.getByText('Reply.').waitFor({timeout: 15000});
const chats = log.filter(l => l.what === 'chat-request');
const sandboxAt = log.find(l => l.what === 'sandbox-response').at;
const result = {mode, waiting, chatRequests: chats.length, firstSandboxId: chats[0]?.sandboxId ?? null, chatAfterSandbox: chats[0]?.at >= sandboxAt, toolbar: await p.locator('[aria-label="Preview"]').first().innerText().catch(() => ''), errs};
const ok = mode === 'ok' ? result.firstSandboxId === 'sbx_first' && result.chatAfterSandbox && result.chatRequests === 1 && waiting.thinking : result.chatRequests === 1 && result.firstSandboxId === null;
